mapper.select:
SELECT m.id, m.warehouse_id, m.sku_id, m.movement_type, m.source_document_type, m.source_document_id, m.source_document_item_id, m.quantity, m.unit_snapshot, m.unit_cost, m.before_quantity, m.after_quantity, m.occurred_at, m.operator, m.created_at, r.receipt_no, w.warehouse_code, w.name AS warehouse_name, k.sku_code, k.spec_name AS sku_name, k.spec_values, p.name AS product_name FROM inventory_movement m LEFT JOIN purchase_receipt r ON r.id = m.source_document_id AND m.source_document_type = 'PURCHASE_RECEIPT_ITEM' LEFT JOIN warehouse w ON w.id = m.warehouse_id LEFT JOIN product_sku k ON k.id = m.sku_id LEFT JOIN product_spu p ON p.id = k.spu_id WHERE m.deleted = FALSE
AND m.warehouse_id = #{query.warehouseId}
AND m.sku_id = #{query.skuId}
AND k.sku_code ILIKE CONCAT('%', #{query.skuCode}, '%')
AND m.movement_type = #{query.movementType}
AND m.source_document_type = #{query.sourceDocumentType}
AND m.source_document_id = #{query.sourceDocumentId}
AND m.occurred_at >= #{query.occurredFrom}
AND m.occurred_at < #{query.occurredTo}
ORDER BY m.occurred_at DESC, m.id DESC

SELECT count(*) FROM inventory_movement
WHERE deleted = FALSE
  AND source_document_type = #{sourceDocumentType}
  AND source_document_item_id = #{sourceDocumentItemId}
